import { app,shell } from "electron"
import theLogger from "electron-log"
import JSZip from "jszip"
import fs from "fs"
import path from "path"
import codffect from "../api/codffect"
import local_store from "../storage/local_store"

// theLogger.transports.file.level = 'debug'
theLogger.transports.file.maxSize = 1002430 // 10M
theLogger.transports.file.format = '[{y}-{m}-{d} {h}:{i}:{s}.{ms}] [{level}]{scope} {text}'
let date = new Date()
let datestr = date.getFullYear() + '-' + (date.getMonth() + 1) + '-' + date.getDate()
// theLogger.transports.file.file = app.getPath('userData') + '\\electron_log\\app\\' + datestr + '.log'
theLogger.transports.file.fileName = datestr + '.log'
console.log("logger Path:"+theLogger.transports.file.getFile().path)

export default {
    logDebug(msg:any){
        if(local_store.config.debugSwitch){
            this.log(msg)
        }
    },
    log(msg:any){
        if(typeof(msg)==typeof({})||typeof(msg)==typeof([])){
            msg = JSON.stringify(msg)
        }
        if(app.isPackaged){
            theLogger.debug(msg)
            console.log("[Logger]",msg)
        }else{
            console.log("[Logger]",msg)
        }
    },
    openLogDir(){
        let logPath = this.getLogPath();
        let base = path.basename(logPath);
        let dirPath = logPath.replace(base,'')
        return shell.openPath(dirPath);
    },
    getLogPath():string{
        return theLogger.transports.file.getFile().path
    },
    async compressAndSend(){
        let logPath = this.getLogPath();
        let base = path.basename(logPath);
        let dirPath = logPath.replace(base,'')

        let logContent = fs.readFileSync(logPath)

        let zip = new JSZip();
        zip.file(base,logContent)
        let content = await zip.generateAsync( {type: 'nodebuffer', 
        compression: 'DEFLATE', 
        compressionOptions: { level: 9, }})

        let conf = local_store.config;
        let zipFilePath = conf.uuid+".zip";
        fs.writeFileSync(zipFilePath,content)
        await codffect.uploadFile(zipFilePath)
        fs.unlinkSync(zipFilePath)
    }
}