import { app } from "electron";
import codffect from "../api/codffect"
import local_store from "../storage/local_store";
import build from "../base/build";

export default {
    poke(eventKey:string,params:any){
        let conf = local_store.config;
        let postBody:any = {};

        let dat:string = "";
        dat += eventKey;
        dat += "__";
        dat += new Date().getTime();
        dat += "__";
        if(params){
            for(let key in params){
                dat = dat + key + "::"+params[key] + "&&";
            }
        }
        postBody.Datas = [dat];

        let common:any = {};
        common.deviceid = conf.uuid;
        common.os = process.platform;
        common.osv = process.getSystemVersion();
        common.appv = app.getVersion();
        common.from = build.from;
        codffect.statisticPoke(common,postBody);
    }
}